  shoulder.addColorStop(0.55, 'rgba(231, 244, 250, 0.48)');
  shoulder.addColorStop(1, 'rgba(181, 211, 225, 0)');
  ctx.fillStyle = shoulder;
  ctx.beginPath();
  ctx.ellipse(6.0, 0, 18.0, 15.0, 0, 0, TAU);
