    ctx.fillStyle = 'rgba(255, 184, 92, 0.95)';
    ctx.beginPath();
    ctx.arc(31.9, side * 4.7, 0.58, 0, TAU);
    ctx.fill();
    ctx.fillStyle = 'rgba(255, 255, 255, 0.8)';
