  ctx.lineWidth = 0.8;
  ctx.beginPath();
  ctx.moveTo(33.8, 0);
  ctx.quadraticCurveTo(36.6, 1.4, 39.0, 0.2);
  ctx.stroke();
  ctx.fillStyle = '#f8f4e9';
