  ctx.beginPath();
  ctx.ellipse(43.0, -1.4, 4.2, 2.1, -0.2, 0, TAU);
  ctx.ellipse(47.0, -3.0, 3.0, 1.6, -0.3, 0, TAU);
  ctx.fill();

