  for (let i = 0; i < 12; i++) {
    const a = i * 1.9;
    const d = 9 + (i % 5) * 3.2;
    ctx.fillStyle = `rgba(255, 255, 255, ${0.45 + (i % 3) * 0.15})`;
    ctx.beginPath();
    ctx.arc(Math.cos(a) * d + 4, Math.sin(a) * d * 0.75, 0.55 + (i % 3) * 0.25, 0, TAU);
    ctx.fill();
  }
}

